    본문: "예수께서 대답하여 가라사대 심은 것마다 내 천부께서 심으시지 않은 것은 뽑힐 것이니",
    표1_원어분석: [
        {"원어":"φυτεία (퓌테이아)", "의미_문법":"심은 것 - 명사. 식물, 심어진 나무", "설교포인트":"하나님이 심으신 것과 사람이 심은 것의 구별"},
        {"원어":"πατήρ (파테르)", "의미_문법":"아버지 - 명사. 하늘에 계신 아버지 하나님", "설교포인트":"하나님만이 참된 심는 분이시다"},
        {"원어":"ἐκριζωθήσεται (에크리조데세타이)", "의미_문법":"뽑힐 것이다 - 동사 수동태 미래. 뿌리째 뽑히다", "설교포인트":"하나님이 심지 않은 것은 반드시 제거된다"},
        {"원어":"οὐράνιος (우라니오스)", "의미_문법":"하늘의 - 형용사. 천상의, 하늘에 속한", "설교포인트":"하늘 아버지의 뜻만이 영원히 남는다"}
    ],
    표2_역사적배경: [
        {"항목":"심음과 뽑힘의 비유", "내용":"구약에서 이스라엘은 하나님이 심으신 포도나무로 비유됨(사 5:1-7). 바리새인의 가르침은 하나님이 심지 않은 잡초와 같아 뽑힐 것이라는 선언", "목회적활용":"하나님의 기원이 없는 종교적 가르침은 영원할 수 없다"},
        {"항목":"바리새인에 대한 심판 선언", "내용":"제자들의 걱정에 대한 예수님의 답변. 바리새인을 두려워할 필요 없다는 확언. 그들의 가르침은 하나님께서 심지 않은 것이므로 결국 뽑힐 것", "목회적활용":"거짓 가르침은 아무리 강해 보여도 결국 무너진다"},
        {"항목":"천부의 주권", "내용":"'내 천부'라는 표현으로 하나님과의 특별한 관계를 선언하시며, 동시에 모든 것의 기원과 결말이 하나님의 주권 안에 있음을 밝히심", "목회적활용":"하나님의 주권을 신뢰하면 사람을 두려워하지 않는다"}
    ],
    표3_신학적의미: [
        {"교리":"하나님의 주권적 심판", "설명":"하나님이 심지 않은 모든 것은 결국 뽑힌다. 이는 거짓 교사와 잘못된 가르침에 대한 하나님의 최종 심판을 예고", "관련구절":"마 13:29-30, 시 1:4-6, 잠 12:3, 사 5:5-6"},
        {"교리":"참된 기원의 중요성", "설명":"신앙의 기원이 하나님에게서 왔는지 사람에게서 왔는지가 그 영속성을 결정함", "관련구절":"행 5:38-39, 약 1:17, 요 15:1-2, 고전 3:6-7"},
        {"교리":"거짓 교사의 종말", "설명":"하나님이 세우지 않은 종교 지도자와 가르침은 영원할 수 없다. 시간이 지나면 진위가 드러남", "관련구절":"벧후 2:1-3, 유 1:12-13, 마 7:15-20, 딤전 4:1"}
    ],
    표4_예표론: [
        {"구분":"하나님이 심으신 것", "내용":"하나님의 기원에서 나온 참된 가르침과 참된 교회", "그리스도연결":"참 포도나무이신 그리스도와 그 안에 심겨진 성도 (요 15:1-5)"},
        {"구분":"뽑힐 것", "내용":"하나님이 심지 않은 거짓 가르침의 제거", "그리스도연결":"알곡과 가라지를 분리하시는 그리스도의 심판 (마 13:40-43)"},
        {"구분":"천부의 농부되심", "내용":"하나님이 심고 가꾸시는 분이심", "그리스도연결":"농부이신 아버지와 포도나무이신 그리스도 (요 15:1)"}
    ],
    표5_매튜헨리: [
        {"영어원문":"Every plant which my heavenly Father hath not planted shall be rooted up. The traditions of the Pharisees were plants not of God's planting.", "한국어번역":"내 하늘 아버지께서 심지 않은 모든 식물은 뽑힐 것이다. 바리새인의 유전은 하나님이 심지 않은 식물이었다.", "핵심통찰":"하나님의 기원이 없는 전통은 결국 뽑힌다"},
        {"영어원문":"Whatever is not of God's planting will not be of his protecting; therefore fear them not.", "한국어번역":"하나님이 심지 않은 것은 하나님의 보호도 받지 못할 것이니 그러므로 두려워하지 말라.", "핵심통찰":"하나님의 보호 없는 것은 두려워할 필요가 없다"},
        {"영어원문":"God will sooner or later reckon with the corrupters of his word, and they shall be rooted up.", "한국어번역":"하나님은 조만간 자신의 말씀을 부패시킨 자들과 결산하실 것이며 그들은 뽑힐 것이다.", "핵심통찰":"말씀을 왜곡하는 자들의 결말은 정해져 있다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"하나님이 심지 않은 것은 뽑힌다 - 참된 기원의 중요성", "예화_적용":"뿌리가 없는 나무는 바람에 쓰러진다"},
        {"대지":"서론", "내용":"제자들이 바리새인의 분노를 걱정하자 예수님은 놀라운 답변을 하셨다. 두려워할 필요 없다. 하나님이 심지 않은 것은 결국 뽑힐 것이니까. 이 말씀은 참된 것과 거짓된 것의 최종 결말에 대한 선언이다", "예화_적용":"역사 속에서 수많은 이단과 거짓 가르침이 결국 사라졌다"},
        {"대지":"1대지: 하나님이 심으신 것 (참된 기원)", "내용":"하나님에게서 기원한 진리, 교회, 사역은 영원히 남는다. 기원이 하나님께 있는지가 가장 중요", "예화_적용":"우리의 사역과 삶의 기원이 하나님에게 있는지 점검하라"},
        {"대지":"2대지: 심지 않은 것은 뽑힌다 (거짓의 종말)", "내용":"아무리 강력해 보이는 종교적 체계도 하나님의 기원이 없으면 결국 무너진다", "예화_적용":"거짓 가르침의 강성함에 두려워하지 말라. 시간이 증명한다"},
        {"대지":"3대지: 천부의 주권 (하나님의 통치)", "내용":"심는 것도, 뽑는 것도 하나님의 주권이다. 우리는 하나님의 주권을 신뢰하면 된다", "예화_적용":"결과는 하나님께 맡기고 우리는 진리 위에 서면 된다"},
        {"대지":"결론", "내용":"바리새인의 분노가 두렵습니까? 그들의 가르침은 하나님이 심지 않은 것입니다. 결국 뽑힐 것입니다. 우리의 신앙, 우리의 삶이 하나님에게 뿌리를 두고 있다면 흔들리지 않을 것입니다", "예화_적용":"하나님이 심으신 뿌리 위에 서 있는 사람은 어떤 바람에도 쓰러지지 않는다"}
    ],
